.stage{padding:var(--sec, clamp(120px, 12vw, 260px)) var(--gutter, clamp(24px, 5vw, 96px));position:relative}
.stage.tight{padding-block:clamp(48px,5vw,90px)}
.stage.full{padding-inline:0}

/* B55 · מחוון שמחליק בין פריטי תפריט */
.tg{display:inline-flex;position:relative;background:var(--card, #fff);border:1px solid var(--line, #e4e4ee);
  border-radius:999px;padding:5px;gap:2px;max-width:100%;flex-wrap:wrap}
.tg-pill{position:absolute;top:5px;left:0;height:calc(100% - 10px);border-radius:999px;background:var(--ink, #16182b);z-index:0}
.tg a{position:relative;z-index:1;padding:10px 20px;border-radius:999px;font-size:15px;color:var(--muted, #6a6d85);
  text-decoration:none;white-space:nowrap;transition:color .22s}
/* הצבע הלבן נקבע לפי מי שהגלולה נמצאת מתחתיו ברגע זה (hot), ולא לפי מי שנבחר (on).
   אחרת בהובר הטקסט האפור יושב על גלולה כהה, והנבחר נשאר לבן על רקע בהיר. */
.tg a.hot{color:var(--bg, #f7f7fa)}
.tg a:hover{color:var(--ink, #16182b)}
.tg a.hot:hover{color:var(--bg, #f7f7fa)}
.tg a:focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:2px}
.tg-wrap{display:grid;justify-items:center;gap:26px}
.tg-out{color:var(--muted, #6a6d85);font-size:15px}
.tg-out b{color:var(--ink, #16182b)}
@media(max-width:520px){.tg a{padding:10px 13px;font-size:14px}}

