/* S05D · מינימליזם עריכתי · פרטים */
.cwrap{container-type:inline-size}
.q{--accent:#4A6EF6;--accent-text:#3552D8;--btn-solid:#3B5BDB;--tint-12:color-mix(in srgb,var(--accent, #4a3aff) 12%,#fff);--tint-4:color-mix(in srgb,var(--accent, #4a3aff) 4%,#fff);
 --ink:#111;--muted:#6b7280;--muted-strong:#4b5563;--border:#eaeaea;--border-2:#e5e7eb;--surface:#fff;--surface-muted:#f3f4f6;--err:#d92d20;
 --r-control:12px;--r-card:16px;--ease:cubic-bezier(.2,.6,.2,1);--shadow-soft:0 6px 20px rgba(17,24,39,.08);--shadow-shot:0 30px 60px rgba(17,24,39,.16);
 --sec:112px;--gut:clamp(20px,4cqi,64px);
 background:var(--surface);color:var(--ink, #16182b);font-family:"Ploni","Heebo",system-ui,sans-serif;font-size:18px;line-height:1.36;overflow:hidden;position:relative;isolation:isolate;-webkit-font-smoothing:antialiased}
