/* B63 · שאלות נפוצות כשיחה */
.cq{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(28px,6vw,112px);align-items:start;max-width:min(1180px,94vw);margin-inline:auto}
.cq-side{position:sticky;top:clamp(80px,12vh,140px)}
.cq-side h3{font-size:clamp(30px,3.6vw,54px);line-height:1.1;margin:0 0 16px;font-weight:400}
.cq-side h3 b{font-weight:800;display:block}
.cq-side p{margin:0;color:var(--muted, #6a6d85);font-size:17px;line-height:1.6;max-width:36ch}
.cq-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}
.cq-item{display:flex;flex-direction:column;align-items:flex-start}
/* השאלה: הודעה שנשלחה. יושבת בצד ההתחלה (ימין בעברית) עם פינה חדה אחת בצד השולח */
.cq-q{display:inline-flex;align-items:center;gap:12px;max-width:100%;background:none;border:0;padding:4px 0;font:inherit;text-align:start;cursor:pointer;color:inherit}
.cq-txt{padding:16px 24px;border-radius:30px 6px 30px 30px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);font-size:clamp(16px,1.4vw,19px);font-weight:600;line-height:1.4;
  box-shadow:0 14px 30px -18px color-mix(in srgb,var(--ink, #16182b) 60%,transparent);transition:background-color .3s,color .3s,transform .3s cubic-bezier(.2,.6,.2,1)}
.cq-mark{flex:none;width:44px;height:44px;border-radius:50%;background:var(--ink, #16182b);position:relative;transition:background-color .3s,transform .4s cubic-bezier(.2,.6,.2,1)}
.cq-mark::before,.cq-mark::after{content:"";position:absolute;inset:50% 13px auto;height:2px;margin-top:-1px;border-radius:2px;background:var(--bg, #f7f7fa)}
.cq-mark::after{transform:rotate(90deg)}
.cq-q:hover .cq-txt{transform:translateY(-2px)}
.cq-q:focus-visible{outline:none}
.cq-q:focus-visible .cq-txt{outline:2px solid var(--accent, #4a3aff);outline-offset:3px}
.cq-item.open .cq-txt{background:var(--accent, #4a3aff);color:var(--accent-ink, #fff)}
.cq-item.open .cq-mark{background:var(--accent, #4a3aff);transform:rotate(45deg)}
.cq-item.open .cq-mark::before,.cq-item.open .cq-mark::after{background:var(--accent-ink, #fff)}
/* התשובה: גובה אמיתי ב-grid-template-rows, ובתוכו בועה שקופצת פנימה רק אחרי שהשורה נפתחה */
.cq-a{display:grid;grid-template-rows:0fr;width:100%;transition:grid-template-rows .42s cubic-bezier(.2,.6,.2,1)}
.cq-item.open .cq-a{grid-template-rows:1fr}
.cq-a>div{overflow:hidden}
.cq-reply{display:flex;align-items:flex-end;gap:12px;justify-content:flex-end;padding:10px 4px 28px;
  opacity:0;transform:translateY(12px) scale(.97);transform-origin:left bottom;transition:opacity .25s,transform .25s cubic-bezier(.2,.6,.2,1)}
.cq-item.open .cq-reply{opacity:1;transform:none;transition:opacity .35s .12s,transform .45s .12s cubic-bezier(.2,.6,.2,1)}
.cq-bub{max-width:min(560px,100%);background:var(--card, #fff);color:var(--ink, #16182b);border:1px solid var(--line, #e4e4ee);padding:18px 24px;
  border-radius:26px 26px 26px 6px;font-size:16px;line-height:1.65;box-shadow:0 14px 34px -20px color-mix(in srgb,var(--ink, #16182b) 40%,transparent)}
.cq-bub p{margin:0}
.cq-av{flex:none;width:42px;height:42px;border-radius:50%;box-shadow:0 0 0 3px var(--card, #fff);font-size:15px}
@media (max-width:820px){.cq{grid-template-columns:1fr}.cq-side{position:static}}
@media (prefers-reduced-motion: reduce){.cq-a,.cq-reply,.cq-item.open .cq-reply,.cq-txt,.cq-mark{transition-duration:.01ms;transition-delay:0s}}

