/* מחלקות עזר של המאגר שהרכיב הזה משתמש בהן */
.ph{display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;border-radius:var(--r, 14px)}
.ph-a{background:linear-gradient(160deg,#3b5bdb,#748ffc)}
.ph-b{background:linear-gradient(160deg,#5f3dc4,#9775fa)}
.ph-c{background:linear-gradient(160deg,#0b7285,#3bc9db)}
.ph-d{background:linear-gradient(160deg,#2b8a3e,#69db7c)}
.ph-e{background:linear-gradient(160deg,#e8590c,#ffa94d)}

/* G149 · שתי תמונות שנפרשות לצדדים וחושפות את הפרויקט */
.pf{overflow-x:clip;padding-block:var(--sec, clamp(120px, 12vw, 260px))}
.pf-head{text-align:center;max-width:52ch;margin:0 auto clamp(20px,6vh,64px);padding-inline:var(--gutter, clamp(24px, 5vw, 96px))}
.pf-head h2{margin:0 0 12px;font-size:var(--fs-h2, clamp(28px, 1.9vw + 0.5rem, 52px))}
.pf-head p{margin:0;color:var(--muted, #6a6d85);line-height:1.6}
.pf-card{--iw:min(30vw,50vh);position:relative;min-height:max(100vh,calc(var(--iw) * 1.25 + 112px));display:grid;place-items:center;padding-inline:var(--gutter, clamp(24px, 5vw, 96px))}
.pf-txt{position:relative;z-index:1;text-align:center;max-width:min(440px,36vw)}
.pf-txt h3{margin:0 0 16px;font-size:clamp(28px,3vw,46px);font-weight:600}
.pf-txt p{margin:0 0 32px;color:var(--muted, #6a6d85);font-size:16px;line-height:1.6}
.pf-btn{display:inline-block;border:1px solid var(--ink, #16182b);color:var(--ink, #16182b);padding:12px 24px;text-decoration:none;font-size:15px;transition:background-color .3s,color .3s}
.pf-btn:hover{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
/* שתי התמונות יושבות בדיוק באותו מקום, במרכז ומעל הטקסט. JS מזיז אותן */
.pf-img{position:absolute;left:50%;top:50%;z-index:2;width:var(--iw);aspect-ratio:4/5;margin:calc(var(--iw) * -.625) 0 0 calc(var(--iw) * -.5);will-change:transform;
  box-shadow:0 30px 60px -30px color-mix(in srgb,var(--ink, #16182b) 55%,transparent)}
.pf-img .ph{position:absolute;inset:0;border-radius:0;font-size:0}
.pf-img.r{z-index:3}
@media (max-width:767px){
  /* קצב אנכי מובייל: 32 מעל ומתחת לכל כרטיס = 64 בין כרטיס לכרטיס, כמו קצב הסקשן במובייל */
  .pf-card{--iw:min(56vw,300px);min-height:0;display:flex;flex-direction:column;align-items:center;padding-block:32px}
  .pf-stack{position:relative;width:100%;height:calc(var(--iw) * 1.25 + 32px);margin-bottom:32px}
  .pf-txt{max-width:36ch}
}
@media (min-width:768px){.pf-stack{display:contents}}

