function drawer(root, burger){
  const panel=root.querySelector(".md-panel"), scrim=root.querySelector(".md-scrim"), closeBtn=root.querySelector(".md-close");
  const doc=document.documentElement; let last=null;
  // numbering for the stagger: every top-level row and every sub link gets its own index
  root.querySelectorAll(".md-item").forEach((el,i)=>el.style.setProperty("--i",i));
  root.querySelectorAll(".md-sub").forEach(s=>s.querySelectorAll("a").forEach((a,j)=>a.style.setProperty("--j",j)));
  panel.inert=true;
  function set(open){
    root.classList.toggle("open",open);
    panel.inert=!open;
    if(burger) burger.setAttribute("aria-expanded",String(open));
    // scroll lock without a jump (fixed 23.9.2026): lock the real scroller, <html>, and keep the scrollbar's
    // space reserved with scrollbar-gutter. The old way (overflow on body + padding-inline-end) failed twice:
    // with overflow-x:clip on html the body lock never reaches the viewport, and in RTL inline-end is the LEFT side,
    // so the whole header jumped and grew a margin on the left.
    doc.style.scrollbarGutter=open?"stable":"";
    doc.style.overflow=open?"hidden":"";
    if(open){last=document.activeElement;setTimeout(()=>closeBtn.focus(),180);}
    else{root.querySelectorAll(".md-sub.open").forEach(s=>toggleSub(s.previousElementSibling,false)); if(last)last.focus();}
  }
  function toggleSub(btn,force){
    const sub=btn.nextElementSibling, open=force!==undefined?force:!sub.classList.contains("open");
    sub.classList.toggle("open",open); btn.setAttribute("aria-expanded",String(open));
    sub.querySelectorAll("a").forEach(a=>a.tabIndex=open?0:-1);
  }
  root.querySelectorAll(".md-acc").forEach(b=>{toggleSub(b,false);b.addEventListener("click",()=>toggleSub(b));});
  if(burger) burger.addEventListener("click",()=>set(!root.classList.contains("open")));
  closeBtn.addEventListener("click",()=>set(false));
  scrim.addEventListener("click",()=>set(false));
  root.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>set(false)));
  addEventListener("keydown",e=>{
    if(!root.classList.contains("open"))return;
    if(e.key==="Escape"){set(false);return;}
    if(e.key!=="Tab")return;
    // focus trap: tab cycles inside the drawer
    const f=[...panel.querySelectorAll("a,button")].filter(x=>x.tabIndex!==-1&&x.offsetParent!==null);
    const i=f.indexOf(document.activeElement);
    const n=e.shiftKey?(i<=0?f.length-1:i-1):(i===f.length-1?0:i+1);
    e.preventDefault(); f[n].focus();
  });
  return set;
}

function headroom(el,opt){
  opt=opt||{};
  // in the vault the page is a scrolling frame; on a real site there is no [data-scroller] and it listens to window
  var sc=el.closest("[data-scroller]")||window, tol=opt.tol||6, last=0, raf=0;
  function pos(){return sc===window?window.scrollY:sc.scrollTop;}
  function upd(){
    raf=0;
    var y=pos(), d=y-last, top=opt.top!=null?opt.top:el.offsetHeight+24;
    el.classList.toggle("is-scrolled",y>8);
    if(opt.on)opt.on(y);
    // hold: an open menu, or keyboard focus inside the header, keeps it on screen
    var hold=el.classList.contains("menu-open")||!!el.querySelector(":focus-visible");
    if(y<=top||hold){el.classList.remove("is-hidden");last=y;return;}
    // tolerance: a slow trackpad drift does not flicker it; the distance accumulates until it is a real gesture
    if(Math.abs(d)<tol)return;
    el.classList.toggle("is-hidden",d>0);
    last=y;
  }
  sc.addEventListener("scroll",function(){if(!raf)raf=requestAnimationFrame(upd);},{passive:true});
  el.addEventListener("focusin",upd);
  last=pos(); upd();
  return upd;
}
headroom(document.querySelector(".h2x"));
drawer(document.getElementById("md-h2"), document.querySelector(".h2x .burger"));

