/* HD4 · הדר מינימלי צף עם תפריט מסך מלא */
/* ---- demo frame (not part of the header): a scrolling mini page ---- */
.hx{position:relative;height:min(80vh,760px);overflow:auto;overscroll-behavior:contain;margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border:1px solid var(--line, #e4e4ee);border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);isolation:isolate;scrollbar-width:thin}
.hx-slot{position:sticky;top:0;height:0;z-index:20}
.hx-hero{min-height:86%;display:flex;flex-direction:column;justify-content:flex-end;gap:16px;padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 64px;
  background:linear-gradient(160deg,color-mix(in srgb,var(--accent, #4a3aff) 34%,var(--ink, #16182b)),var(--ink, #16182b) 72%);color:var(--bg, #f7f7fa)}
.hx-hero.is-light{background:linear-gradient(180deg,color-mix(in srgb,var(--accent, #4a3aff) 9%,var(--bg, #f7f7fa)),var(--bg, #f7f7fa));color:var(--ink, #16182b)}
.hx-hero small{font-size:14px;font-weight:600;opacity:.8}
.hx-hero h3{margin:0;max-width:16ch;font-size:clamp(34px,4.4vw,72px);line-height:1.02;font-weight:700}
.hx-hero p{margin:0;max-width:44ch;font-size:17px;line-height:1.5;opacity:.82}
.hx-sec{display:grid;grid-template-columns:1fr 1.2fr;gap:var(--gap, clamp(16px, 1.6vw, 36px));align-items:center;padding:96px var(--gutter, clamp(24px, 5vw, 96px));border-top:1px solid var(--line, #e4e4ee);scroll-margin-top:88px}
.hx-sec h4{margin:0 0 12px;font-size:clamp(24px,2.2vw,36px);line-height:1.1}
.hx-sec p{margin:0;max-width:40ch;font-size:16px;line-height:1.6;color:var(--muted, #6a6d85)}
