@media (max-width:700px){.fs{grid-template-columns:1fr;align-content:end;padding:112px var(--gutter, clamp(24px, 5vw, 96px)) 48px}}
@media (prefers-reduced-motion:reduce){.fs,.fs *{transition-duration:.01ms!important;transition-delay:0s!important}}

