.ft-legal nav{display:flex;flex-wrap:wrap;gap:8px 20px}
.ft-legal nav a{opacity:.7}
.ft-credit{margin-inline-start:auto!important}
.ft-credit a{opacity:.7}
@media (hover:hover) and (pointer:fine){.ftw a:hover,.ft-legal nav a:hover,.ft-credit a:hover{opacity:1;color:var(--accent, #4a3aff)}}
.ft-dark{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
@media (hover:hover) and (pointer:fine){.ft-dark a:hover,.ft-dark .ft-legal nav a:hover,.ft-dark .ft-credit a:hover{color:color-mix(in srgb,var(--accent, #4a3aff) 45%,var(--bg, #f7f7fa))}}
.ft-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:52px;padding:0 28px;border-radius:12px;border:0;background:var(--accent, #4a3aff);color:var(--accent-ink, #fff)!important;
  font:inherit;font-size:16px;font-weight:600;cursor:pointer;transition:transform .18s cubic-bezier(.2,.6,.2,1),background .2s cubic-bezier(.2,.6,.2,1)}
.ft-btn svg{width:18px;height:18px}
@media (hover:hover) and (pointer:fine){.ft-btn:hover{transform:translateY(-2px)}}
.ft-rv{opacity:0;transform:translateY(16px);transition:opacity .6s cubic-bezier(.2,.6,.2,1),transform .6s cubic-bezier(.2,.6,.2,1);transition-delay:calc(var(--i,0) * 80ms)}
.is-in .ft-rv{opacity:1;transform:none}
@media (max-width:760px){.ft-credit{margin-inline-start:0!important;flex-basis:100%}}
@media (prefers-reduced-motion:reduce){.ftw *,.ft-rv{transition-duration:.01ms!important;transition-delay:0s!important}.ft-rv{opacity:1;transform:none}}
.ft9{display:grid;gap:40px;padding:72px 32px 40px;background:color-mix(in srgb,var(--ink, #16182b) 4%,var(--bg, #f7f7fa));color:var(--ink, #16182b)}
.ft9-head{display:flex;flex-wrap:wrap;align-items:end;justify-content:space-between;gap:16px}
.ft9-head h2{margin:0;font-size:clamp(24px,2.2vw,34px)}
.ft9-lang{display:flex;gap:4px;padding:4px;border-radius:12px;background:var(--card, #fff)}
.ft9-lang a{min-height:40px;display:inline-flex;align-items:center;padding:0 14px;border-radius:8px;font-weight:600;font-size:14px}
.ft9-lang a[aria-current="page"]{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)!important}
.ft9-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.ft9-card{display:grid;gap:8px;padding:24px;border-radius:16px;background:var(--card, #fff);transition:transform .3s cubic-bezier(.2,.6,.2,1),box-shadow .3s cubic-bezier(.2,.6,.2,1)}
.ft9-card h3{margin:0;font-size:20px;opacity:1}
.ft9-card span{font-size:14px;color:var(--muted, #6a6d85)}
.ft9-card .go{margin-top:8px;display:inline-flex;align-items:center;gap:8px;font-weight:600;font-size:14px;color:var(--accent, #4a3aff)!important}
.ft9-card .go svg{width:16px;height:16px}
@media (hover:hover) and (pointer:fine){.ft9-card:hover{transform:translateY(-3px);box-shadow:0 16px 40px color-mix(in srgb,var(--ink, #16182b) 10%,transparent)}}
@media (max-width:900px){.ft9{padding:56px 20px 32px}.ft9-grid{grid-template-columns:1fr}}

