entries.css:
/* CV1 · פס פעולה בטלפון עם בורר ערוצים ושעות חיות */
.cx *{box-sizing:border-box}
.cx{--cx-err:color-mix(in srgb,#d23b22 72%,var(--ink, #16182b));font-size:16px;line-height:1.6;color:var(--ink, #16182b)}
.cx :where(a){color:inherit}
.cx :where(h2,h3){text-wrap:balance}
.cx :where(p,small,li){text-wrap:pretty}
.cx :focus-visible{outline:2px solid var(--accent, #4a3aff);outline-offset:3px;border-radius:8px}
.cx-btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 24px;border:0;border-radius:14px;
  background:var(--accent, #4a3aff);color:var(--accent-ink, #fff);font:inherit;font-size:16px;font-weight:600;text-decoration:none;cursor:pointer;white-space:nowrap;
  transition:transform .18s cubic-bezier(.2,.6,.2,1),background .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
.cx-btn svg{width:20px;height:20px;flex:none}
.cx-btn:active{transform:scale(.97)}
.cx-btn.is-ghost{background:transparent;color:var(--ink, #16182b);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 22%,transparent)}
@media (hover:hover) and (pointer:fine){.cx-btn:hover{transform:translateY(-1px)}.cx-btn.is-ghost:hover{box-shadow:inset 0 0 0 1.5px var(--ink, #16182b)}
  .cx a:hover .ic-arr,.cx-btn:hover .ic-arr{transform:translateX(-4px)}}
.ic-arr{transition:transform .2s cubic-bezier(.2,.6,.2,1)}
[dir="ltr"] .ic-arr{rotate:180deg}
.cx-rv{opacity:0;transform:translateY(16px);transition:opacity .5s cubic-bezier(.2,.6,.2,1),transform .5s cubic-bezier(.2,.6,.2,1);transition-delay:calc(var(--i,0) * 80ms)}
.is-in .cx-rv{opacity:1;transform:none}
.cx-t{unicode-bidi:isolate;font-variant-numeric:tabular-nums}
/* the demo switch: lets the reviewer see every state. Not part of the component you copy. */
.cx-demo{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 24px;padding:6px;border-radius:14px;background:color-mix(in srgb,var(--ink, #16182b) 5%,transparent);font-size:13px;width:max-content;max-width:100%}
.cx-demo > span{padding:0 10px;font-weight:600;color:var(--muted, #6a6d85)}
.cx-demo button{min-height:36px;padding:0 14px;border:0;border-radius:10px;background:none;font:inherit;font-weight:600;color:var(--ink, #16182b);cursor:pointer;transition:background .18s cubic-bezier(.2,.6,.2,1),color .18s cubic-bezier(.2,.6,.2,1)}
.cx-demo button[aria-pressed="true"]{background:var(--card, #fff);box-shadow:0 1px 3px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.cx-demo input{min-height:36px;padding:0 12px;border:0;border-radius:10px;background:var(--card, #fff);font:inherit;font-size:14px;color:var(--ink, #16182b);width:220px}
@media (prefers-reduced-motion:reduce){.cx *,.cx *::before,.cx *::after{transition-duration:.01ms!important;transition-delay:0s!important;animation-duration:.01ms!important;animation-iteration-count:1!important}.cx-rv{opacity:1;transform:none}}
.cxs{display:grid;place-items:center;padding:24px var(--gutter, clamp(24px, 5vw, 96px)) 56px}
.cx-phone{position:relative;width:min(390px,100%);height:min(78vh,760px);border-radius:40px;overflow:hidden;background:var(--bg, #f7f7fa);isolation:isolate;
  box-shadow:0 0 0 10px var(--ink, #16182b),0 32px 64px color-mix(in srgb,var(--ink, #16182b) 24%,transparent);container-type:inline-size}
.cx-scr{height:100%;overflow:auto;overscroll-behavior:contain;scrollbar-width:none}
.cx-scr::-webkit-scrollbar{display:none}
/* the bar's room is made inside the footer, never as padding under it: padding on body shows as a band of the page
   colour below a dark footer (Profix, 23.9.2026) */
.cx-page{padding-bottom:0}
.cx-hero{min-height:78cqh;display:flex;flex-direction:column;justify-content:flex-end;gap:14px;padding:88px 24px 40px;
  background:linear-gradient(170deg,color-mix(in srgb,var(--accent, #4a3aff) 30%,var(--ink, #16182b)),var(--ink, #16182b) 70%);color:var(--bg, #f7f7fa)}
.cx-hero small{font-size:13px;font-weight:600;opacity:.8}
.cx-hero h3{margin:0;font-size:32px;line-height:1.08;font-weight:700}
.cx-hero p{margin:0;font-size:16px;line-height:1.5;opacity:.82}
.cx-hero .cx-btn{align-self:flex-start;margin-top:8px}
.cx-sec{padding:56px 24px}
.cx-sec:nth-of-type(even){background:var(--card, #fff)}
.cx-sec small{font-size:13px;font-weight:600;color:var(--muted, #6a6d85)}
.cx-sec h4{margin:8px 0 12px;font-size:24px;line-height:1.15}
.cx-sec p{margin:0;font-size:16px;line-height:1.6;color:var(--muted, #6a6d85)}
.cx-blk{margin-top:24px;aspect-ratio:4/3;border-radius:20px;background:color-mix(in srgb,var(--ink, #16182b) 7%,var(--bg, #f7f7fa))}
.cx-end{padding:56px 24px 40px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
.cx-end h4{margin:0 0 8px;font-size:26px;line-height:1.15}
.cx-end p{margin:0 0 24px;opacity:.75}
.cx-end input{display:block;width:100%;min-height:52px;margin-bottom:12px;padding:0 16px;border:0;border-radius:12px;background:color-mix(in srgb,var(--bg, #f7f7fa) 10%,transparent);
  color:var(--bg, #f7f7fa);font:inherit;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--bg, #f7f7fa) 18%,transparent);transition:box-shadow .18s cubic-bezier(.2,.6,.2,1)}
.cx-end input::placeholder{color:color-mix(in srgb,var(--bg, #f7f7fa) 55%,transparent)}
.cx-end input:focus{outline:0;box-shadow:inset 0 0 0 2px var(--accent, #4a3aff)}
.cx-end .cx-btn{width:100%}
.cx-foot{padding:24px 24px calc(24px + 72px);font-size:13px;color:var(--muted, #6a6d85)}

/* ---- the bar itself ---- */
.mbar{position:fixed;inset-inline:0;bottom:0;z-index:40;display:flex;align-items:center;gap:8px;padding:10px 12px max(10px,env(safe-area-inset-bottom));
  background:color-mix(in srgb,var(--card, #fff) 92%,transparent);-webkit-backdrop-filter:blur(16px) saturate(1.4);backdrop-filter:blur(16px) saturate(1.4);
  box-shadow:0 -16px 40px color-mix(in srgb,var(--ink, #16182b) 12%,transparent);
  transform:translateY(calc(100% + 16px));transition:transform .32s cubic-bezier(.76,0,.24,1)}
.mbar.is-on{transform:none;transition-timing-function:cubic-bezier(.2,.6,.2,1)}
/* mobile only on a real site; inside the vault's phone it shows at any window width */
@media (min-width:768px){.mbar{display:none}}
.cx-phone .mbar{display:flex;position:absolute}
.mb-go{flex:1;min-width:0}
.mb-ic{flex:none;display:grid;place-items:center;width:52px;height:52px;border-radius:14px;color:var(--ink, #16182b);background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent);transition:transform .18s cubic-bezier(.2,.6,.2,1),background .2s cubic-bezier(.2,.6,.2,1)}
.mb-ic svg{width:22px;height:22px}
.mb-ic:active{transform:scale(.94)}
.cv1-bar .mb-go{min-width:0}
.mb-talk{position:relative;display:inline-flex;align-items:center;gap:8px;min-height:52px;padding:0 16px;border:0;border-radius:14px;background:color-mix(in srgb,var(--ink, #16182b) 6%,transparent);
  color:var(--ink, #16182b);font:inherit;font-size:15px;font-weight:600;cursor:pointer;white-space:nowrap;transition:background .2s cubic-bezier(.2,.6,.2,1),transform .18s cubic-bezier(.2,.6,.2,1)}
.mb-talk:active{transform:scale(.96)}
.sheet-open .mb-talk{background:var(--ink, #16182b);color:var(--bg, #f7f7fa)}
.mb-dot{width:8px;height:8px;border-radius:50%;background:var(--muted, #6a6d85);flex:none}
.is-open-now .mb-dot{background:#2f9e5b;box-shadow:0 0 0 3px color-mix(in srgb,#2f9e5b 22%,transparent)}
/* the sheet grows out of the button that opened it */
.mb-sheet{position:absolute;bottom:calc(100% + 10px);inset-inline-end:12px;width:min(300px,calc(100cqw - 24px));padding:8px;border-radius:20px;background:var(--card, #fff);
  box-shadow:0 24px 56px color-mix(in srgb,var(--ink, #16182b) 22%,transparent),0 0 0 1px color-mix(in srgb,var(--ink, #16182b) 6%,transparent);
  transform-origin:bottom left;opacity:0;transform:translateY(8px) scale(.96);visibility:hidden;
  transition:opacity .18s cubic-bezier(.2,.6,.2,1),transform .24s cubic-bezier(.2,.6,.2,1),visibility 0s linear .24s}
[dir="ltr"] .mb-sheet{transform-origin:bottom right}
.sheet-open .mb-sheet{opacity:1;transform:none;visibility:visible;transition-delay:0s}
.mb-status{display:flex;align-items:center;gap:10px;margin:0;padding:10px 12px 12px;font-size:13px;font-weight:600;color:var(--muted, #6a6d85)}
.mb-sheet ul{list-style:none;margin:0;padding:0;display:grid;gap:4px}
.mb-sheet li{opacity:0;transform:translateY(6px);transition:opacity .2s cubic-bezier(.2,.6,.2,1),transform .24s cubic-bezier(.2,.6,.2,1)}
.sheet-open .mb-sheet li{opacity:1;transform:none;transition-delay:calc(60ms + var(--i) * 60ms)}
.mb-sheet a{display:flex;align-items:center;gap:14px;min-height:56px;padding:8px 12px;border-radius:14px;text-decoration:none;transition:background .18s cubic-bezier(.2,.6,.2,1)}
