.nf-h{margin:0 0 24px;font-size:clamp(28px,3.8vw,40px);line-height:1.12;font-weight:700}
.nf-guess{display:grid;grid-template-columns:1fr auto;gap:4px 16px;align-items:center;margin:0 0 40px;padding:20px 24px;border-radius:20px;background:var(--ink, #16182b);color:var(--bg, #f7f7fa);text-decoration:none;
  transition:transform .2s cubic-bezier(.2,.6,.2,1),box-shadow .2s cubic-bezier(.2,.6,.2,1)}
