.nf-s input{width:100%;min-height:52px;padding:0 16px;padding-inline-start:48px;border:0;border-radius:14px;background:var(--card, #fff);font:inherit;color:var(--ink, #16182b);
  box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 12%,transparent);transition:box-shadow .18s cubic-bezier(.2,.6,.2,1)}
