.cx-demo button[aria-pressed="true"]{background:var(--card, #fff);box-shadow:0 1px 3px color-mix(in srgb,var(--ink, #16182b) 14%,transparent)}
.cx-demo input{min-height:36px;padding:0 12px;border:0;border-radius:10px;background:var(--card, #fff);font:inherit;font-size:14px;color:var(--ink, #16182b);width:220px}
@media (prefers-reduced-motion:reduce){.cx *,.cx *::before,.cx *::after{transition-duration:.01ms!important;transition-delay:0s!important;animation-duration:.01ms!important;animation-iteration-count:1!important}.cx-rv{opacity:1;transform:none}}
.cxw{margin-inline:var(--gutter, clamp(24px, 5vw, 96px));border-radius:var(--r, 14px);background:var(--bg, #f7f7fa);box-shadow:0 0 0 1px var(--line, #e4e4ee);overflow:hidden;isolation:isolate}
.cxw-in{max-width:640px;margin-inline:auto;padding:72px 24px 88px}
@media (max-width:700px){.cxw-in{padding:48px 20px 64px}}
.f8-h{margin:0 0 8px;font-size:clamp(26px,3.4vw,36px);line-height:1.15;font-weight:700}
.f8-sub{margin:0 0 28px;color:var(--muted, #6a6d85)}
.f8 form{display:grid;gap:16px}
.f8 label{display:grid;gap:8px;font-size:14px;font-weight:600}
.f8 input,.f8 textarea{width:100%;min-height:52px;padding:14px 16px;border:0;border-radius:14px;background:var(--card, #fff);font:inherit;font-weight:400;color:var(--ink, #16182b);resize:vertical;
  box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--ink, #16182b) 12%,transparent);transition:box-shadow .18s cubic-bezier(.2,.6,.2,1)}
.f8 textarea{min-height:96px}
.f8 input:focus,.f8 textarea:focus{outline:0;box-shadow:inset 0 0 0 2px var(--accent, #4a3aff)}
.f8-btn{justify-self:start;min-width:180px;overflow:hidden}
.f8-btn [data-lab]{display:inline-block}
.f8-btn [data-lab].in{animation:f8-lab .22s cubic-bezier(.2,.6,.2,1)}
@keyframes f8-lab{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.f8-spin{display:none;width:18px;height:18px;border-radius:50%;box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--accent-ink, #fff) 30%,transparent);border-top:2px solid var(--accent-ink, #fff);animation:f8-spin .8s linear infinite}
@keyframes f8-spin{to{transform:rotate(360deg)}}
[data-state="sending"] .f8-spin{display:block}
[data-state="sending"] .f8-btn{cursor:progress}
.f8-ok{display:none;width:20px;height:20px}
.f8-ok path{stroke-dasharray:24;stroke-dashoffset:24;animation:f8-draw .35s cubic-bezier(.2,.6,.2,1) .05s forwards}
@keyframes f8-draw{to{stroke-dashoffset:0}}
[data-state="sent"] .f8-ok{display:block}
[data-state="sent"] .f8-btn{background:var(--ink, #16182b);color:var(--bg, #f7f7fa);pointer-events:none}
/* the panel opens by its row track, so nothing below it jumps */
.f8-panel{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s cubic-bezier(.2,.6,.2,1)}
.f8-panel.is-open{grid-template-rows:1fr}
.f8-panel > div{overflow:hidden;min-height:0}
.f8-box{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;margin-top:8px;padding:18px 20px;border-radius:16px;background:color-mix(in srgb,var(--cx-err) 7%,var(--bg, #f7f7fa))}
[data-kind="offline"] .f8-box{background:color-mix(in srgb,var(--ink, #16182b) 6%,var(--bg, #f7f7fa))}
[data-kind="ok"] .f8-box{background:color-mix(in srgb,var(--accent, #4a3aff) 9%,var(--bg, #f7f7fa))}
.f8-ic{grid-row:span 2;width:24px;height:24px;color:var(--cx-err)}
[data-kind="offline"] .f8-ic{color:var(--muted, #6a6d85)}
[data-kind="ok"] .f8-ic{color:var(--accent, #4a3aff)}
.f8-ic svg{display:block;width:24px;height:24px}
.f8-ic > span{display:none}
[data-kind="error"] .f8-ic .i-err,[data-kind="offline"] .f8-ic .i-off,[data-kind="ok"] .f8-ic .i-ok{display:block}
.f8-box b{font-size:16px;line-height:1.4}
.f8-box p{margin:0;display:flex;align-items:center;gap:10px;font-size:15px;color:var(--muted, #6a6d85)}
.f8-ring{width:20px;height:20px;flex:none;transform:rotate(-90deg)}
.f8-ring circle{fill:none;stroke:var(--cx-err);stroke-width:2.5;stroke-dasharray:50.3;stroke-dashoffset:0}
.f8-ring.run circle{animation:f8-count var(--t,5s) linear forwards}
@keyframes f8-count{to{stroke-dashoffset:50.3}}
[data-kind="offline"] .f8-ring,[data-kind="ok"] .f8-ring,.is-final .f8-ring{display:none}
.f8-acts{grid-column:2;display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.f8-acts .cx-btn{min-height:44px;padding:0 16px;font-size:14px}
[data-kind="ok"] .f8-acts{display:none}
/* waiting for the network is not an action the visitor can take: the button says so and steps back */
[data-state="offline"] .f8-btn{background:color-mix(in srgb,var(--ink, #16182b) 8%,var(--bg, #f7f7fa));color:var(--ink, #16182b);cursor:default}
/* offline: a slow breathing dot says "waiting", not "broken" */
.f8-wait{display:none;width:8px;height:8px;border-radius:50%;background:var(--muted, #6a6d85);animation:f8-breathe 1.6s cubic-bezier(.2,.6,.2,1) infinite}
[data-kind="offline"] .f8-wait{display:block}
@keyframes f8-breathe{50%{opacity:.25}}

